package net.sf.jaer.hardwareinterface.usb.cypressfx3libusb;

import eu.seebetter.ini.chips.davis.imu.IMUSample;
import eu.seebetter.ini.chips.davis.imu.IMUSampleType;
import java.lang.reflect.Method;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Headless semantic vectors for the production SciDVS GAER state machine.
 * Expected packed values below are fixed legacy-format oracles, not values
 * generated by the decoder under test.
 */
public final class SciDVSGaerDecoderDemo {

    private static int assertions;

    private SciDVSGaerDecoderDemo() {
    }

    public static void main(final String[] args) throws Exception {
        testSourcePayloadClassification();
        testGroupExpansionAndPersistentY();
        testTimestampsResetWrapAndExternalInput();
        testTimestampRegressionAccounting();
        testSpecialFrameAndExposureInformation();
        testApsSamplesAndGeometry();
        testImuAssemblyAcrossTransfersAndFlips();
        testMisc11AndOddBufferContract();
        System.out.println("SCIDVS GAER SEMANTIC ASSERTIONS=" + assertions);
        System.out.println("SCIDVS GAER SEMANTIC VECTORS PASS");
    }

    private static void testSourcePayloadClassification() {
        final ByteBuffer metadata = words(0x8001, 0x7001, 0xFFFF);
        metadata.order(ByteOrder.BIG_ENDIAN);
        final int originalPosition = metadata.position();
        final int originalLimit = metadata.limit();
        final ByteOrder originalOrder = metadata.order();
        require(!SciDVSGaerDecoder.containsSourcePayload(metadata),
                "timestamp and wrap words are transport metadata, not source payload");
        require(metadata.position() == originalPosition
                && metadata.limit() == originalLimit
                && metadata.order() == originalOrder,
                "payload classification does not mutate caller buffer state");
        require(SciDVSGaerDecoder.containsSourcePayload(words(0x100A)),
                "a DVS row word is source payload");
        require(SciDVSGaerDecoder.containsSourcePayload(words(0x2001)),
                "a DVS group word is source payload");
        require(SciDVSGaerDecoder.containsSourcePayload(words(0x0001)),
                "a non-timestamp special word is conservatively source payload");
        require(!SciDVSGaerDecoder.containsSourcePayload(ByteBuffer.allocate(0)),
                "an empty transfer has no source payload");
        final ByteBuffer odd = ByteBuffer.allocate(1).put((byte) 0x55).flip();
        require(SciDVSGaerDecoder.containsSourcePayload(odd),
                "an odd trailing byte is conservatively source payload");
        require(odd.position() == 0 && odd.limit() == 1,
                "odd-buffer classification leaves caller bounds unchanged");
    }

    private static void testGroupExpansionAndPersistentY() {
        checkGroup(0x00, new int[0], new boolean[0]);
        checkGroup(0x01, new int[]{42397696}, new boolean[]{false});
        checkGroup(0x10, new int[]{42399744}, new boolean[]{true});
        checkGroup(0x11, new int[]{42397696, 42399744}, new boolean[]{false, true});
        checkGroup(0xFF, new int[]{
            42397696, 42393600, 42389504, 42385408,
            42399744, 42395648, 42391552, 42387456
        }, new boolean[]{false, false, false, false, true, true, true, true});

        final RecordingSink highGroup = new RecordingSink();
        final SciDVSGaerDecoder highGroupDecoder = new SciDVSGaerDecoder(defaultConfig());
        highGroupDecoder.decode(words(0x8064, 0x100A, 0x3B01), highGroup);
        require(highGroup.polarity.size() == 1, "group 27 emits one event through code 3");
        require(highGroup.polarity.get(0).packedAddress == 41955328,
                "group 27 fixed packed address");
        require(highGroup.polarity.get(0).x == 108 && highGroup.polarity.get(0).y == 10,
                "group 27 semantic x/y");

        final RecordingSink inverted = new RecordingSink();
        new SciDVSGaerDecoder(config(true, false, false, false, false, false, false))
                .decode(words(0x8064, 0x100A, 0x2001), inverted);
        require(inverted.polarity.size() == 1, "invertXY emits one event");
        require(inverted.polarity.get(0).packedAddress == 465608704,
                "invertXY fixed packed address");
        require(inverted.polarity.get(0).x == 0 && inverted.polarity.get(0).y == 10,
                "invertXY retains semantic sensor coordinate");

        final RecordingSink missingY = new RecordingSink();
        new SciDVSGaerDecoder(defaultConfig()).decode(words(0x2001), missingY);
        require(missingY.polarity.size() == 1, "legacy missing-Y context is accepted");
        require(missingY.polarity.get(0).packedAddress == 524742656,
                "missing-Y legacy default dvsLastY=0 packs Y=125");
        require(missingY.polarity.get(0).y == 125, "missing-Y semantic Y is packed legacy Y=125");

        final RecordingSink staleY = new RecordingSink();
        final SciDVSGaerDecoder staleYDecoder = new SciDVSGaerDecoder(defaultConfig());
        staleYDecoder.decode(words(0x100A), staleY);
        staleYDecoder.decode(words(0x107E, 0x2002), staleY);
        require(staleY.polarity.size() == 1, "event survives out-of-range Y");
        require(staleY.polarity.get(0).packedAddress == 42393600,
                "out-of-range Y leaves prior Y=10 in force");
        require(staleY.polarity.get(0).x == 1 && staleY.polarity.get(0).y == 10,
                "out-of-range Y leaves semantic coordinate unchanged");

        final RecordingSink outOfRangeGroup = new RecordingSink();
        new SciDVSGaerDecoder(defaultConfig()).decode(words(0x100A, 0x3CFF), outOfRangeGroup);
        require(outOfRangeGroup.polarity.isEmpty(),
                "legacy group-base range check rejects base 112");

        final RecordingSink split = new RecordingSink();
        final SciDVSGaerDecoder splitDecoder = new SciDVSGaerDecoder(defaultConfig());
        splitDecoder.decode(words(0x100A), split);
        splitDecoder.decode(words(0x2001), split);
        final RecordingSink joined = new RecordingSink();
        new SciDVSGaerDecoder(defaultConfig()).decode(words(0x100A, 0x2001), joined);
        require(split.polarity.equals(joined.polarity),
                "Y context persists across transfers and equals joined decoding");
    }

    private static void checkGroup(final int bits, final int[] expectedPacked,
            final boolean[] expectedPolarity) {
        final RecordingSink sink = new RecordingSink();
        new SciDVSGaerDecoder(defaultConfig()).decode(words(0x8064, 0x100A, 0x2000 | bits), sink);
        require(sink.polarity.size() == Integer.bitCount(bits),
                "group 0x" + Integer.toHexString(bits) + " bit count");
        require(sink.polarity.size() == expectedPacked.length,
                "group 0x" + Integer.toHexString(bits) + " expected array length");
        for (int i = 0; i < expectedPacked.length; i++) {
            final Polarity got = sink.polarity.get(i);
            require(got.packedAddress == expectedPacked[i],
                    "group 0x" + Integer.toHexString(bits) + " packed address " + i);
            require(got.on == expectedPolarity[i],
                    "group 0x" + Integer.toHexString(bits) + " polarity " + i);
            require(got.y == 10, "non-invert packed/semantic Y equals wire Y=10");
            require(got.timestamp == 100, "group timestamp is 100");
        }
    }

    private static void testTimestampsResetWrapAndExternalInput() {
        final RecordingSink sink = new RecordingSink();
        final SciDVSGaerDecoder decoder = new SciDVSGaerDecoder(defaultConfig());
        decoder.decode(words(0x8064, 0x100A, 0x2001, 0x7003, 0x2010), sink);
        decoder.decode(words(0x8005, 0x2002, 0x0001, 0x0002, 0x0003, 0x0004), sink);

        require(ints(sink.polarity, p -> p.timestamp).equals(Arrays.asList(100, 98304, 98309)),
                "timestamp, wrap, and post-wrap timestamp are exact across transfers");
        require(sink.timestampResets == 1, "one timestamp-reset notification");
        require(sink.external.size() == 3, "three external events");
        require(ints(sink.external, e -> e.code).equals(Arrays.asList(2, 3, 4)),
                "external semantic edge codes 2/3/4");
        require(ints(sink.external, e -> e.packedAddress).equals(Arrays.asList(1026, 1027, 1028)),
                "external fixed packed addresses");
        require(ints(sink.external, e -> e.timestamp).equals(Arrays.asList(0, 0, 0)),
                "external timestamps are zero after reset");
    }

    private static void testTimestampRegressionAccounting() throws Exception {
        final RecordingSink sink = new RecordingSink();
        final SciDVSGaerDecoder decoder = new SciDVSGaerDecoder(defaultConfig());
        decoder.decode(words(0x0001, 0x87D0, 0x100A, 0x2001,
                0x876C, 0x2002), sink);

        require(ints(sink.polarity, p -> p.timestamp).equals(Arrays.asList(2000, 1900)),
                "wire timestamps remain unmodified for forensic integrity");

        final Method count = SciDVSGaerDecoder.class.getDeclaredMethod(
                "getNonMonotonicTimestampCount");
        final Method maximum = SciDVSGaerDecoder.class.getDeclaredMethod(
                "getMaxBackwardTimestampUs");
        count.setAccessible(true);
        maximum.setAccessible(true);
        require(((Number) count.invoke(decoder)).longValue() == 1L,
                "one in-epoch backward timestamp is counted independently of logging");
        require(((Number) maximum.invoke(decoder)).intValue() == 100,
                "largest in-epoch backward timestamp magnitude is retained");

        decoder.decode(words(0x0001), sink);
        require(((Number) count.invoke(decoder)).longValue() == 0L,
                "a positive hardware reset marker starts a fresh disorder count");
        require(((Number) maximum.invoke(decoder)).intValue() == 0,
                "a positive hardware reset marker clears the prior maximum");
    }

    private static void testSpecialFrameAndExposureInformation() {
        final RecordingSink sink = new RecordingSink();
        final SciDVSGaerDecoder decoder = new SciDVSGaerDecoder(defaultConfig());
        decoder.decode(words(
                0x0008, 0x000E, 0x000F, 0x000A,
                0x0009, 0x000A,
                0x0010, 0x0011,
                0x0020, 0x0021, 0x0022, 0x0023,
                0x0030, 0x0031, 0x0032, 0x0033, 0x0034,
                0x0000, 0x0012, 0x0002), sink);

        require(sink.frameStarts.equals(Arrays.asList(false, true)),
                "global and rolling frame-start notifications");
        require(sink.frameEnds.equals(Arrays.asList(false, true)),
                "frame-end notifications retain shutter mode");
        require(sink.exposureStarts == 1 && sink.exposureEnds == 1,
                "exposure start/end semantic notifications");
        require(sink.external.size() == 1 && sink.external.get(0).packedAddress == 1026,
                "reserved/info/unsupported specials do not corrupt following external event");
    }

    private static void testApsSamplesAndGeometry() {
        final RecordingSink sink = new RecordingSink();
        final SciDVSGaerDecoder decoder = new SciDVSGaerDecoder(config(
                false, false, false, false, false, false, false, 2, 2));
        decoder.decode(words(
                0x8032, 0x0008,
                0x000B, 0x4001, 0x4002, 0x000D,
                0x000B, 0x4003, 0x4004, 0x000D,
                0x000C, 0x4005, 0x4006, 0x000D,
                0x000C, 0x4007, 0x4008, 0x000D,
                0x000A), sink);

        final int[] expectedPacked = {
            -2143289343, -2147483646, -2143285245, -2147479548,
            -2143288315, -2147482618, -2143284217, -2147478520
        };
        final int[] expectedX = {0, 0, 1, 1, 0, 0, 1, 1};
        final int[] expectedY = {1, 0, 1, 0, 1, 0, 1, 0};
        require(sink.aps.size() == expectedPacked.length, "eight APS samples emitted");
        for (int i = 0; i < expectedPacked.length; i++) {
            final Aps sample = sink.aps.get(i);
            require(sample.packedAddress == expectedPacked[i], "APS fixed packed address " + i);
            require(sample.adcData == i + 1, "APS ADC data " + i);
            require(sample.x == expectedX[i] && sample.y == expectedY[i], "APS x/y " + i);
            require(sample.resetRead == (i < 4), "APS reset/signal read type " + i);
            require(sample.pixelFirst == (i == 0 || i == 4), "APS first-pixel marker " + i);
            require(sample.pixelLast == (i == 3 || i == 7), "APS last-pixel marker " + i);
            require(sample.timestamp == 50, "APS timestamp " + i);
        }
        require(sink.frameStarts.equals(Arrays.asList(false)), "APS global frame start");
        require(sink.frameEnds.equals(Arrays.asList(false)), "APS global frame end");

        final RecordingSink transformed = new RecordingSink();
        new SciDVSGaerDecoder(config(false, true, true, true, false, false, false, 2, 3))
                .decode(words(0x0008, 0x000B, 0x4009), transformed);
        require(transformed.aps.size() == 1, "transformed APS sample emitted");
        require(transformed.aps.get(0).packedAddress == -2147475447,
                "APS invertXY/flipX/flipY fixed packed address");
        require(transformed.aps.get(0).x == 2 && transformed.aps.get(0).y == 0,
                "APS invertXY/flipX/flipY semantic coordinate");
    }

    private static void testImuAssemblyAcrossTransfersAndFlips() {
        final int[] bytes = {
            0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
            0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E
        };
        final RecordingSink sink = new RecordingSink();
        final SciDVSGaerDecoder decoder = new SciDVSGaerDecoder(defaultConfig());
        decoder.decode(words(0x804D, 0x0005, 0x53E0,
                0x5001, 0x5002, 0x5003, 0x5004, 0x5005, 0x5006, 0x5007), sink);
        decoder.decode(words(0x5008, 0x5009, 0x500A, 0x500B, 0x500C, 0x500D, 0x500E, 0x0007), sink);
        require(sink.imu.size() == 1, "14 IMU bytes across transfers emit one sample");
        require(sink.imu.get(0).timestamp == 77, "IMU callback timestamp");
        assertImuRaw(sink.imu.get(0).sample,
                new short[]{0x0102, 0x0304, 0x0506, 0x0708, 0x090A, 0x0B0C, 0x0D0E});

        final int[] invalid = new int[16];
        invalid[0] = 0x0005;
        invalid[1] = 0x53E0;
        for (int i = 0; i < 13; i++) {
            invalid[i + 2] = 0x5000 | bytes[i];
        }
        invalid[15] = 0x0007;
        decoder.decode(words(invalid), sink);
        require(sink.imu.size() == 1, "13-byte IMU sample is discarded");

        final RecordingSink flipped = new RecordingSink();
        final int[] complete = new int[18];
        complete[0] = 0x0005;
        complete[1] = 0x53E0;
        for (int i = 0; i < bytes.length; i++) {
            complete[i + 2] = 0x5000 | bytes[i];
        }
        complete[16] = 0x0007;
        complete[17] = 0x0002;
        new SciDVSGaerDecoder(config(false, false, false, false, true, true, true))
                .decode(words(complete), flipped);
        require(flipped.imu.size() == 1, "flipped IMU sample emitted");
        assertImuRaw(flipped.imu.get(0).sample,
                new short[]{-0x0102, -0x0304, -0x0506, 0x0708, -0x090A, -0x0B0C, -0x0D0E});
    }

    private static void assertImuRaw(final IMUSample sample, final short[] expected) {
        final IMUSampleType[] types = IMUSampleType.values();
        require(types.length == expected.length, "IMU type count");
        for (int i = 0; i < types.length; i++) {
            require(sample.getSensorRaw(types[i]) == expected[i], "IMU raw value " + types[i]);
        }
    }

    private static void testMisc11AndOddBufferContract() {
        final RecordingSink patchSink = new RecordingSink();
        final SciDVSGaerDecoder decoder = new SciDVSGaerDecoder(defaultConfig());
        decoder.decode(words(0x6805, 0x100A, 0x2001, 0x682A), patchSink);
        require(patchSink.addressPatches.equals(Arrays.asList(5, 42)),
                "misc11 reports masks even when raw sink has no previous event");
        require(patchSink.polarity.size() == 1, "misc11 emits no extra semantic event");

        final ByteBuffer odd = ByteBuffer.allocate(5).order(ByteOrder.LITTLE_ENDIAN);
        odd.putShort((short) 0x8009);
        odd.putShort((short) 0x0002);
        odd.put((byte) 0x55);
        odd.flip();
        final RecordingSink oddSink = new RecordingSink();
        decoder.decode(odd, oddSink);
        require(oddSink.external.size() == 1, "odd buffer decodes complete words only");
        require(oddSink.external.get(0).timestamp == 9, "odd buffer complete-word timestamp");
        require(odd.limit() == 4, "legacy odd-buffer truncation permanently reduces caller limit");
        require(odd.position() == 0, "legacy decoder leaves caller position unchanged");
        require(odd.order() == ByteOrder.LITTLE_ENDIAN, "legacy decoder leaves caller byte order little-endian");
    }

    private static SciDVSGaerDecoder.Config defaultConfig() {
        return config(false, false, false, false, false, false, false);
    }

    private static SciDVSGaerDecoder.Config config(final boolean dvsInvertXY,
            final boolean apsInvertXY, final boolean apsFlipX, final boolean apsFlipY,
            final boolean imuFlipX, final boolean imuFlipY, final boolean imuFlipZ) {
        return config(dvsInvertXY, apsInvertXY, apsFlipX, apsFlipY,
                imuFlipX, imuFlipY, imuFlipZ, 112, 126);
    }

    private static SciDVSGaerDecoder.Config config(final boolean dvsInvertXY,
            final boolean apsInvertXY, final boolean apsFlipX, final boolean apsFlipY,
            final boolean imuFlipX, final boolean imuFlipY, final boolean imuFlipZ,
            final int apsSizeX, final int apsSizeY) {
        return new SciDVSGaerDecoder.Config(
                SciDVSHardwareInterface.CHIP_DAVIS240C,
                112, 126, dvsInvertXY,
                apsSizeX, apsSizeY, apsInvertXY, apsFlipX, apsFlipY,
                imuFlipX, imuFlipY, imuFlipZ);
    }

    private static ByteBuffer words(final int... words) {
        final ByteBuffer buffer = ByteBuffer.allocate(words.length * Short.BYTES)
                .order(ByteOrder.LITTLE_ENDIAN);
        for (final int word : words) {
            buffer.putShort((short) word);
        }
        return buffer.flip();
    }

    private static <T> List<Integer> ints(final List<T> values, final IntField<T> field) {
        final List<Integer> result = new ArrayList<>(values.size());
        for (final T value : values) {
            result.add(field.get(value));
        }
        return result;
    }

    private static void require(final boolean condition, final String description) {
        assertions++;
        if (!condition) {
            throw new AssertionError(description);
        }
    }

    private interface IntField<T> {
        int get(T value);
    }

    private static final class RecordingSink implements SciDVSGaerSink {
        final List<Polarity> polarity = new ArrayList<>();
        final List<External> external = new ArrayList<>();
        final List<Aps> aps = new ArrayList<>();
        final List<Imu> imu = new ArrayList<>();
        final List<Boolean> frameStarts = new ArrayList<>();
        final List<Boolean> frameEnds = new ArrayList<>();
        final List<Integer> addressPatches = new ArrayList<>();
        int timestampResets;
        int exposureStarts;
        int exposureEnds;

        @Override
        public void onTimestampReset() {
            timestampResets++;
        }

        @Override
        public void onExternalInput(final int code, final int packedAddress, final int timestamp) {
            external.add(new External(code, packedAddress, timestamp));
        }

        @Override
        public void onFrameStart(final boolean rollingShutter, final int timestamp) {
            frameStarts.add(rollingShutter);
        }

        @Override
        public void onFrameEnd(final boolean rollingShutter, final int timestamp) {
            frameEnds.add(rollingShutter);
        }

        @Override
        public void onExposureStart(final int timestamp) {
            exposureStarts++;
        }

        @Override
        public void onExposureEnd(final int timestamp) {
            exposureEnds++;
        }

        @Override
        public void onPolarity(final int packedAddress, final int x, final int y,
                final boolean on, final int timestamp) {
            polarity.add(new Polarity(packedAddress, x, y, on, timestamp));
        }

        @Override
        public void onApsSample(final int packedAddress, final int adcData,
                final int x, final int y, final boolean resetRead,
                final boolean pixelFirst, final boolean pixelLast, final int timestamp) {
            aps.add(new Aps(packedAddress, adcData, x, y, resetRead,
                    pixelFirst, pixelLast, timestamp));
        }

        @Override
        public void onImuSample(final IMUSample sample, final int timestamp) {
            imu.add(new Imu(sample, timestamp));
        }

        @Override
        public void onAddressPatch(final int orMask) {
            addressPatches.add(orMask);
        }
    }

    private static final class Polarity {
        final int packedAddress;
        final int x;
        final int y;
        final boolean on;
        final int timestamp;

        Polarity(final int packedAddress, final int x, final int y,
                final boolean on, final int timestamp) {
            this.packedAddress = packedAddress;
            this.x = x;
            this.y = y;
            this.on = on;
            this.timestamp = timestamp;
        }

        @Override
        public boolean equals(final Object other) {
            if (!(other instanceof Polarity)) {
                return false;
            }
            final Polarity that = (Polarity) other;
            return packedAddress == that.packedAddress && x == that.x && y == that.y
                    && on == that.on && timestamp == that.timestamp;
        }

        @Override
        public int hashCode() {
            return packedAddress;
        }
    }

    private static final class External {
        final int code;
        final int packedAddress;
        final int timestamp;

        External(final int code, final int packedAddress, final int timestamp) {
            this.code = code;
            this.packedAddress = packedAddress;
            this.timestamp = timestamp;
        }
    }

    private static final class Aps {
        final int packedAddress;
        final int adcData;
        final int x;
        final int y;
        final boolean resetRead;
        final boolean pixelFirst;
        final boolean pixelLast;
        final int timestamp;

        Aps(final int packedAddress, final int adcData, final int x, final int y,
                final boolean resetRead, final boolean pixelFirst,
                final boolean pixelLast, final int timestamp) {
            this.packedAddress = packedAddress;
            this.adcData = adcData;
            this.x = x;
            this.y = y;
            this.resetRead = resetRead;
            this.pixelFirst = pixelFirst;
            this.pixelLast = pixelLast;
            this.timestamp = timestamp;
        }
    }

    private static final class Imu {
        final IMUSample sample;
        final int timestamp;

        Imu(final IMUSample sample, final int timestamp) {
            this.sample = sample;
            this.timestamp = timestamp;
        }
    }
}
